    fun obtenerNombreProductoPorCodigo(idproducto: String): String? {
        val db = this.readableDatabase
        val cursor = db.rawQuery(
            "SELECT producto FROM Codigos WHERE idproducto = ?",
            arrayOf(idproducto)
        )
        var producto: String? = null
        if (cursor.moveToFirst()) {
            producto = cursor.getString(cursor.getColumnIndexOrThrow("producto"))
        }
        cursor.close()
        return producto
    }

    // Metodo para obtener todos los clientes
    fun obtenerClientes(): List<Cliente> {
        val clientes = mutableListOf<Cliente>()
        val db = this.readableDatabase
        val cursor = db.rawQuery("SELECT * FROM Cliente", null)
        with(cursor) {
            while (moveToNext()) {
                val idcliente = getInt(getColumnIndexOrThrow("idcliente"))
                val cliente = getString(getColumnIndexOrThrow("cliente"))
                clientes.add(
                    Cliente(
                        idcliente,
                        cliente
                    )
                )
            }
        }
        cursor.close()
        return clientes
    }
    fun obtenerRegistrosPorInventario(idInventario: Int?): List<Registro> {

        val lista = mutableListOf<Registro>()
        val db = readableDatabase

        val query = """
        SELECT r.*
        FROM Registros r
        INNER JOIN Registros_Inventario ri
        ON r.idregistro = ri.idregistro
        WHERE ri.idinventarios = ?
        ORDER BY r.idregistro DESC
    """

        val cursor = db.rawQuery(query, arrayOf(idInventario.toString()))

        if (cursor.moveToFirst()) {
            do {
                val registro = Registro(
                    idregistro = cursor.getInt(cursor.getColumnIndexOrThrow("idregistro")),
                    idproducto = cursor.getString(cursor.getColumnIndexOrThrow("idproducto")),
                    tarimas = cursor.getInt(cursor.getColumnIndexOrThrow("tarimas")),
                    cajas = cursor.getInt(cursor.getColumnIndexOrThrow("cajas")),
                    unidades = cursor.getInt(cursor.getColumnIndexOrThrow("unidades")),
                    suelto = cursor.getInt(cursor.getColumnIndexOrThrow("suelto")),
                    total = cursor.getInt(cursor.getColumnIndexOrThrow("total")),
                    idempresas = cursor.getInt(cursor.getColumnIndexOrThrow("idempresas")),
                    idcliente = cursor.getInt(cursor.getColumnIndexOrThrow("idcliente")),
                    idubicacion = cursor.getInt(cursor.getColumnIndexOrThrow("idubicacion")),
                    fecha = cursor.getLong(cursor.getColumnIndexOrThrow("fecha"))
                )
                lista.add(registro)

            } while (cursor.moveToNext())
        }

        cursor.close()
        return lista
    }

    fun obtenerRegistrosPorInventarioNombre(idInventario: Int?): List<RegistroInventarioItem> {
        val lista = mutableListOf<RegistroInventarioItem>()
        val db = readableDatabase

        val query = """
            SELECT r.idregistro, r.tarimas, r.cajas, r.unidades, r.suelto, r.total,
                   u.ubicacion,c.idproducto, c.producto, cl.cliente, e.empresa, c.medida
            FROM Registros r
            INNER JOIN Registros_Inventario ri ON r.idregistro = ri.idregistro
            INNER JOIN Ubicaciones u ON r.idubicacion = u.idubicacion
            INNER JOIN Codigos c ON r.idproducto = c.idproducto
            INNER JOIN Cliente cl ON r.idcliente = cl.idcliente
            INNER JOIN Empresas e ON r.idempresas = e.idempresas
            WHERE ri.idinventarios = ?
            ORDER BY r.idregistro DESC
        """

        val cursor = db.rawQuery(query, arrayOf(idInventario.toString()))

        if (cursor.moveToFirst()) {
            do {
                val item = RegistroInventarioItem(
                    idregistro = cursor.getInt(cursor.getColumnIndexOrThrow("idregistro")),
                    tarimas = cursor.getInt(cursor.getColumnIndexOrThrow("tarimas")).toString(),
                    cajas = cursor.getInt(cursor.getColumnIndexOrThrow("cajas")).toString(),
                    unidades = cursor.getInt(cursor.getColumnIndexOrThrow("unidades")).toString(),
                    suelto = cursor.getInt(cursor.getColumnIndexOrThrow("suelto")).toString(),
                    total = cursor.getInt(cursor.getColumnIndexOrThrow("total")).toString(),
                    ubicacion = cursor.getString(cursor.getColumnIndexOrThrow("ubicacion")),
                    idproducto = cursor.getString(cursor.getColumnIndexOrThrow("idproducto")),
                    producto = cursor.getString(cursor.getColumnIndexOrThrow("producto")),
                    cliente = cursor.getString(cursor.getColumnIndexOrThrow("cliente")),
                    empresa = cursor.getString(cursor.getColumnIndexOrThrow("empresa")),
                    medida = cursor.getString(cursor.getColumnIndexOrThrow("medida"))
                )
                lista.add(item)
            } while (cursor.moveToNext())
        }

        cursor.close()
        return lista
    }

    // Metodo para obtener todos los registros de un inventario específico
    fun obtenerRegistrosDeInventario(idinventarios: Int): List<Registro> {
        val registros = mutableListOf<Registro>()
        val db = this.readableDatabase
        val query = """
            SELECT r.*
            FROM Registros r
            INNER JOIN Registros_Inventario ri ON r.idregistro = ri.idregistro
            WHERE ri.idinventarios = ?
        """
        val cursor = db.rawQuery(query, arrayOf(idinventarios.toString()))
        with(cursor) {
            while (moveToNext()) {
                val idregistro = getInt(getColumnIndexOrThrow("idregistro"))
                val tarimas = getInt(getColumnIndexOrThrow("tarimas"))
                val cajas = getInt(getColumnIndexOrThrow("cajas"))
                val unidades = getInt(getColumnIndexOrThrow("unidades"))
                val suelto = getInt(getColumnIndexOrThrow("suelto"))
                val total = getInt(getColumnIndexOrThrow("total"))
                val fecha = getString(getColumnIndexOrThrow("fecha")).toLongOrNull() ?: System.currentTimeMillis()
                val idubicacion = getInt(getColumnIndexOrThrow("idubicacion"))
                val idproducto = getString(getColumnIndexOrThrow("idproducto"))
                val idcliente = getInt(getColumnIndexOrThrow("idcliente"))
                val idempresa = getInt(getColumnIndexOrThrow("idempresa"))
                registros.add(
                    Registro(
                        idregistro,
                        tarimas,
                        cajas,
                        unidades,
                        suelto,
                        total,
                        fecha,
                        idubicacion,
                        idproducto,
                        idcliente,
                        idempresa
                    )
                )
            }
        }
        cursor.close()
        return registros
    }


