    /// Metodo para limpiar todas las tablas (para pruebas)
    // kotlin
    fun limpiarTablas() {
        val db = writableDatabase
        db.execSQL("DELETE FROM Registros_Inventario")
                // Borrar respetando FK
                db.execSQL("DELETE FROM Registros")

                db.execSQL("DELETE FROM Inventarios")
                db.execSQL("DELETE FROM Ubicaciones")
                db.execSQL("DELETE FROM Empresas")
                db.execSQL("DELETE FROM Codigos")
                db.execSQL("DELETE FROM Cliente")

                // Insertar datos iniciales
                insertarProductosIniciales(db)
                insertatClientesIniciales(db)
                insertarEmpresasIniciales(db)
                insertarUbicacionesIniciales(db)


    }

    fun contarRegistrosPorInventario(idInventario: Int?): Int {
        val db = readableDatabase
        val cursor = db.rawQuery(
            """
                SELECT COUNT(*) 
                FROM Registros_Inventario
                WHERE idinventarios = ?
            """,
            arrayOf(idInventario.toString())
        )
        var total = 0
        if (cursor.moveToFirst()){
            total = cursor.getInt(0)
        }
        cursor.close()
        return total
    }

    fun obtenerIndiceRegistro(idInventario: Int?, idRegistro: Int): Int {
        val db = readableDatabase
        val cursor = db.rawQuery(
            """
        SELECT COUNT(*) 
        FROM Registros_Inventario 
        WHERE idinventarios = ? AND idregistro <= ?
        """,
            arrayOf(idInventario.toString(), idRegistro.toString())
        )

        var indice = 0
        if (cursor.moveToFirst()) {
            indice = cursor.getInt(0)
        }
        cursor.close()
        return indice
    }


    fun obtenerDatosTabla(tabla: String): List<Map<String, String>> {
        val db = readableDatabase
        val cursor = db.rawQuery("SELECT * FROM $tabla", null)

        val lista = mutableListOf<Map<String, String>>()

        cursor.use {
            val columnas = cursor.columnNames

            while (cursor.moveToNext()) {
                val fila = mutableMapOf<String, String>()
                for (col in columnas) {
                    fila[col] = cursor.getString(
                        cursor.getColumnIndexOrThrow(col)
                    ) ?: ""
                }
                lista.add(fila)
            }
        }
        return lista
    }

    fun obtenerNombreInventario(id: Int): String {
        val db = readableDatabase
        val cursor = db.rawQuery(
            "SELECT nombre_inventario FROM Inventarios WHERE idinventarios = ?",
            arrayOf(id.toString())
        )
        var nombre = "Inventario"

        if(cursor.moveToFirst()){
            nombre = cursor.getString(cursor.getColumnIndexOrThrow("nombre_inventario"))
        }

        cursor.close()
        return nombre
    }

    fun eliminarInventarioCompleto(idInventario: Int): Boolean {
        val db = writableDatabase
        db.beginTransaction()

        return try {

            //  1. Obtener registros ligados a ese inventario
            val cursor = db.rawQuery(
                "SELECT idregistro FROM Registros_Inventario WHERE idinventarios = ?",
                arrayOf(idInventario.toString())
            )

            val registrosIds = mutableListOf<Int>()

            if (cursor.moveToFirst()) {
                do {
                    registrosIds.add(cursor.getInt(0))
                } while (cursor.moveToNext())
            }
            cursor.close()

            //  2. Borrar relación
            db.delete(
                "Registros_Inventario",
                "idinventarios = ?",
                arrayOf(idInventario.toString())
            )

            //  3. Borrar registros (solo si no están en otro inventario)
            for (idRegistro in registrosIds) {

                val c = db.rawQuery(
                    "SELECT COUNT(*) FROM Registros_Inventario WHERE idregistro = ?",
                    arrayOf(idRegistro.toString())
                )

                var count = 0
                if (c.moveToFirst()) count = c.getInt(0)
                c.close()

                if (count == 0) {
                    db.delete(
                        "Registros",
                        "idregistro = ?",
                        arrayOf(idRegistro.toString())
                    )
                }
            }

            //  4. Borrar inventario
            db.delete(
                "Inventarios",
                "idinventarios = ?",
                arrayOf(idInventario.toString())
            )

            db.setTransactionSuccessful()
            true

        } catch (e: Exception) {
            e.printStackTrace()
            false
        } finally {
            db.endTransaction()
        }
    }

    fun esInventarioReabierto(idInventario: Int): Boolean {
        val db = readableDatabase

        val cursor = db.rawQuery(
            "SELECT activo FROM Inventarios WHERE idinventarios = ?",
            arrayOf(idInventario.toString())
        )

        var esReabierto = false

        if (cursor.moveToFirst()) {
            esReabierto = cursor.getInt(0) == 3
        }

        cursor.close()
        return esReabierto
    }





}

package com.example.inventario20
import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper


class DBHelper(context: Context) : SQLiteOpenHelper(context.applicationContext, "MiBaseDatos.db", null, 3) {
    override fun onCreate(db: SQLiteDatabase?) {
        db?.execSQL("""
                CREATE TABLE Inventarios (
                    idinventarios INTEGER PRIMARY KEY,
                    nombre_inventario TEXT NOT NULL,
                    fecha_creacion TEXT NOT NULL,      -- formato: 'YYYY-MM-DD HH:MM:SS'
                    fecha_cierre TEXT,                 -- puede ser NULL
                    activo INTEGER NOT NULL            -- 0 = falso, 1 = verdadero
                )    
            """)

        db?.execSQL("""
            CREATE TABLE Registros (
                idregistro INTEGER PRIMARY KEY,
                tarimas INTEGER,
                cajas INTEGER,
                unidades INTEGER,
                suelto INTEGER,
                total INTEGER,
                fecha TEXT NOT NULL,               -- formato: 'YYYY-MM-DD HH:MM:SS'
                idubicacion INTEGER,
                idproducto TEXT,
                idcliente INTEGER,
                idempresas INTEGER,
                FOREIGN KEY (idubicacion) REFERENCES Ubicaciones(idubicacion),
                FOREIGN KEY (idproducto) REFERENCES Codigos(idproducto),
                FOREIGN KEY (idcliente) REFERENCES Cliente(idcliente),
                FOREIGN KEY (idempresas) REFERENCES Empresas(idempresas)
            )    
        """)

        db?.execSQL("""
            CREATE TABLE Registros_Inventario (
                idregistro INTEGER,
                idinventarios INTEGER,
                PRIMARY KEY (idregistro, idinventarios),
                FOREIGN KEY (idregistro) REFERENCES Registros(idregistro),
                FOREIGN KEY (idinventarios) REFERENCES Inventarios(idinventarios)
            )   
        """)

        db?.execSQL("""
            CREATE TABLE Ubicaciones (
                idubicacion INTEGER PRIMARY KEY,
                ubicacion TEXT NOT NULL,
                idempresas INTEGER,
                FOREIGN KEY (idempresas) REFERENCES Empresas(idempresas)
            )
        """)

        db?.execSQL("""
            CREATE TABLE Empresas (
                idempresas INTEGER PRIMARY KEY,
                empresa TEXT NOT NULL
            )
        """)

        db?.execSQL("""
            CREATE TABLE Codigos (
                idproducto TEXT PRIMARY KEY,
                producto TEXT NOT NULL,
                medida TEXT NOT NULL
            )
        """)

        db?.execSQL("""
            CREATE TABLE Cliente (
                idcliente INTEGER PRIMARY KEY,
                cliente TEXT NOT NULL
            )
        """)
        insertarProductosIniciales (db)
        insertatClientesIniciales(db)
        insertarEmpresasIniciales(db)
        insertarUbicacionesIniciales(db)
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        db.execSQL("DROP TABLE IF EXISTS Inventarios")
        db.execSQL("DROP TABLE IF EXISTS Registros")
        db.execSQL("DROP TABLE IF EXISTS Registros_Inventario")
        db.execSQL("DROP TABLE IF EXISTS Ubicaciones")
        db.execSQL("DROP TABLE IF EXISTS Empresas")
        db.execSQL("DROP TABLE IF EXISTS Codigos")
        db.execSQL("DROP TABLE IF EXISTS Cliente")

        onCreate(db)
    }
