    fun obtenerInventarioActivo(): Int? {
        val db = readableDatabase
        val cursor = db.rawQuery(
            """
        SELECT idinventarios  FROM inventarios
        WHERE activo IN (?, ?)
        LIMIT 1
        """,
            arrayOf(
                EstadoInventario.ABIERTO.toString(),
                EstadoInventario.REABIERTO.toString()
            )
        )

        val idinventarios  = if (cursor.moveToFirst()) cursor.getInt(0) else null
        cursor.close()
        return idinventarios
    }



    /// Metodo para obtener todos los inventarios
    fun obtenerTodosLosInventarios(): List<InventarioItem> {
        val lista = mutableListOf<InventarioItem>()
        val db = readableDatabase

        val cursor = db.rawQuery(
            "SELECT * FROM inventarios ORDER BY fecha_creacion DESC",
            null
        )

        while (cursor.moveToNext()) {
            lista.add(
                InventarioItem(
                    idinventarios = cursor.getInt(cursor.getColumnIndexOrThrow("idinventarios")),
                    nombre_inventario = cursor.getString(cursor.getColumnIndexOrThrow("nombre_inventario")),
                    fechaCreacion = cursor.getString(cursor.getColumnIndexOrThrow("fecha_creacion")),
                    fechaCierre = cursor.getString(cursor.getColumnIndexOrThrow("fecha_cierre")),
                    activo = cursor.getInt(cursor.getColumnIndexOrThrow("activo")),
                )
            )
        }

        cursor.close()
        return lista
    }




    // Metodo para obtener todos los registros
    fun obtenerRegistros(): List<Registro> {
        val registros = mutableListOf<Registro>()
        val db = this.readableDatabase
        val cursor = db.rawQuery("SELECT * FROM Registros", null)
        with(cursor) {
            while (moveToNext()) {
                val idregistro = getInt(getColumnIndexOrThrow("idregistro"))
                val tarimas = getInt(getColumnIndexOrThrow("tarimas"))
                val cajas = getInt(getColumnIndexOrThrow("cajas"))
                val unidades = getInt(getColumnIndexOrThrow("unidades"))
                val suelto = getInt(getColumnIndexOrThrow("suelto"))
                val total = getInt(getColumnIndexOrThrow("total"))
                val fecha = getString(getColumnIndexOrThrow("fecha")).toLongOrNull() ?: System.currentTimeMillis()
                val idubicacion = getInt(getColumnIndexOrThrow("idubicacion"))
                val idproducto = getString(getColumnIndexOrThrow("idproducto"))
                val idcliente = getInt(getColumnIndexOrThrow("idcliente"))
                // La columna en la tabla se llama 'idempresas' (plural)
                val idempresas = getInt(getColumnIndexOrThrow("idempresas"))
                registros.add(
                    Registro(
                        idregistro,
                        tarimas,
                        cajas,
                        unidades,
                        suelto,
                        total,
                        fecha,
                        idubicacion,
                        idproducto,
                        idcliente,
                        idempresas
                    )
                )
            }
        }
        cursor.close()
        return registros
    }

