            Empresa(3, "Mextlan")
        )
        for (empresa in empresasIniciales) {
            val values = ContentValues().apply {
                put("idempresas", empresa.idempresas)
                put("empresa", empresa.empresa)
            }
            db?.insert("Empresas", null, values)
        }
    }
