            }
            db?.insert("Ubicaciones", null, values)
        }
    }

    /// Metodo para limpiar todas las tablas (para pruebas)
    // kotlin
    fun limpiarTablas() {
        val db = writableDatabase
        db.execSQL("DELETE FROM Registros_Inventario")
                // Borrar respetando FK
                db.execSQL("DELETE FROM Registros")

                db.execSQL("DELETE FROM Inventarios")
                db.execSQL("DELETE FROM Ubicaciones")
                db.execSQL("DELETE FROM Empresas")
                db.execSQL("DELETE FROM Codigos")
                db.execSQL("DELETE FROM Cliente")

                // Insertar datos iniciales
                insertarProductosIniciales(db)
                insertatClientesIniciales(db)
                insertarEmpresasIniciales(db)
                insertarUbicacionesIniciales(db)


    }

    fun contarRegistrosPorInventario(idInventario: Int?): Int {
        val db = readableDatabase
        val cursor = db.rawQuery(
            """
                SELECT COUNT(*) 
                FROM Registros_Inventario
                WHERE idinventarios = ?
            """,
            arrayOf(idInventario.toString())
        )
        var total = 0
        if (cursor.moveToFirst()){
            total = cursor.getInt(0)
        }
        cursor.close()
        return total
    }

    fun obtenerIndiceRegistro(idInventario: Int?, idRegistro: Int): Int {
        val db = readableDatabase
        val cursor = db.rawQuery(
            """
        SELECT COUNT(*) 
        FROM Registros_Inventario 
        WHERE idinventarios = ? AND idregistro <= ?
        """,
            arrayOf(idInventario.toString(), idRegistro.toString())
        )

        var indice = 0
        if (cursor.moveToFirst()) {
            indice = cursor.getInt(0)
        }
        cursor.close()
        return indice
    }


    fun obtenerDatosTabla(tabla: String): List<Map<String, String>> {
        val db = readableDatabase
        val cursor = db.rawQuery("SELECT * FROM $tabla", null)

        val lista = mutableListOf<Map<String, String>>()

        cursor.use {
            val columnas = cursor.columnNames

            while (cursor.moveToNext()) {
                val fila = mutableMapOf<String, String>()
                for (col in columnas) {
                    fila[col] = cursor.getString(
                        cursor.getColumnIndexOrThrow(col)
                    ) ?: ""
                }
                lista.add(fila)
            }
        }
        return lista
    }

    fun obtenerNombreInventario(id: Int): String {
        val db = readableDatabase
        val cursor = db.rawQuery(
            "SELECT nombre_inventario FROM Inventarios WHERE idinventarios = ?",
            arrayOf(id.toString())
        )
        var nombre = "Inventario"

        if(cursor.moveToFirst()){
            nombre = cursor.getString(cursor.getColumnIndexOrThrow("nombre_inventario"))
        }

        cursor.close()
        return nombre
    }

    fun eliminarInventarioCompleto(idInventario: Int): Boolean {
        val db = writableDatabase
        db.beginTransaction()

        return try {

            //  1. Obtener registros ligados a ese inventario
            val cursor = db.rawQuery(
                "SELECT idregistro FROM Registros_Inventario WHERE idinventarios = ?",
                arrayOf(idInventario.toString())
            )

            val registrosIds = mutableListOf<Int>()

            if (cursor.moveToFirst()) {
                do {
                    registrosIds.add(cursor.getInt(0))
                } while (cursor.moveToNext())
            }
            cursor.close()

            //  2. Borrar relación
            db.delete(
                "Registros_Inventario",
                "idinventarios = ?",
                arrayOf(idInventario.toString())
            )

            //  3. Borrar registros (solo si no están en otro inventario)
            for (idRegistro in registrosIds) {

                val c = db.rawQuery(
                    "SELECT COUNT(*) FROM Registros_Inventario WHERE idregistro = ?",
                    arrayOf(idRegistro.toString())
                )

                var count = 0
                if (c.moveToFirst()) count = c.getInt(0)
                c.close()

                if (count == 0) {
                    db.delete(
                        "Registros",
                        "idregistro = ?",
                        arrayOf(idRegistro.toString())
                    )
                }
            }

            //  4. Borrar inventario
            db.delete(
                "Inventarios",
                "idinventarios = ?",
                arrayOf(idInventario.toString())
            )

            db.setTransactionSuccessful()
            true

        } catch (e: Exception) {
            e.printStackTrace()
            false
        } finally {
            db.endTransaction()
        }
    }

    fun esInventarioReabierto(idInventario: Int): Boolean {
        val db = readableDatabase

        val cursor = db.rawQuery(
            "SELECT activo FROM Inventarios WHERE idinventarios = ?",
            arrayOf(idInventario.toString())
        )

        var esReabierto = false

        if (cursor.moveToFirst()) {
            esReabierto = cursor.getInt(0) == 3
        }

        cursor.close()
        return esReabierto
    }

    //  VALIDACIONES DE INTEGRIDAD REFERENCIAL
    fun validarIntegridadReferencial(): List<String> {
        val errores = mutableListOf<String>()
        val db = readableDatabase

        try {
            // Verificar registros sin ubicación válida
            val cursor1 = db.rawQuery("""
                SELECT COUNT(*) FROM Registros r 
                LEFT JOIN Ubicaciones u ON r.idubicacion = u.idubicacion 
                WHERE u.idubicacion IS NULL
            """, null)
            if (cursor1.moveToFirst() && cursor1.getInt(0) > 0) {
                errores.add("Existen ${cursor1.getInt(0)} registros con ubicaciones inválidas")
            }
            cursor1.close()

            // Verificar registros sin producto válido
            val cursor2 = db.rawQuery("""
                SELECT COUNT(*) FROM Registros r 
                LEFT JOIN Codigos c ON r.idproducto = c.idproducto 
                WHERE c.idproducto IS NULL
            """, null)
            if (cursor2.moveToFirst() && cursor2.getInt(0) > 0) {
                errores.add("Existen ${cursor2.getInt(0)} registros con productos inválidos")
            }
            cursor2.close()

            // Verificar ubicaciones sin empresa válida
            val cursor3 = db.rawQuery("""
                SELECT COUNT(*) FROM Ubicaciones u 
                LEFT JOIN Empresas e ON u.idempresas = e.idempresas 
                WHERE e.idempresas IS NULL
            """, null)
            if (cursor3.moveToFirst() && cursor3.getInt(0) > 0) {
                errores.add("Existen ${cursor3.getInt(0)} ubicaciones con empresas inválidas")
            }
            cursor3.close()

        } catch (e: Exception) {
            errores.add("Error al validar integridad: ${e.message}")
            Log.e("DBHelper", "Error en validación de integridad", e)
        } finally {
            db.close()
        }

        return errores
    }

    //  MÉTODO CON MANEJO DE ERRORES PARA OPERACIONES CRÍTICAS
    fun ejecutarOperacionSegura(operacion: () -> Any?): ResultadoOperacion {
        return try {
            val resultado = operacion()
            ResultadoOperacion.Exito(resultado)
        } catch (e: Exception) {
            Log.e("DBHelper", "Error en operación de BD", e)
            ResultadoOperacion.Error(e.message ?: "Error desconocido")
        }
    }

    // Clase sellada para resultados de operaciones
    sealed class ResultadoOperacion {
        data class Exito(val data: Any?) : ResultadoOperacion()
        data class Error(val mensaje: String) : ResultadoOperacion()
    }
}
